INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38811, 'Deuteronomy 30:16', 'Deuteronomy', 30, 16, 'که چېرې تاسو د خپل څښتن خدای حکمونو ته چې زه یې نن درکوم غاړه کېږدئ، که چېرې د هغه سره مینه وکړئ، اطاعت یې وکړئ او د هغه د ټولو قوانینو څخه پیروي وکړئ، بیا به تاسو نېکمرغه شئ او یو لوی قوم به درڅخه جوړ شي. تاسو ته به خپل څښتن خدای په هغه خاوره کې چې تاسو به یې زر ونیسئ، برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_16.mp3', '', 1761754199, 1761754199),
(38812, 'Deuteronomy 30:17', 'Deuteronomy', 30, 17, 'خو که چېرې سرغړونه وکړئ او غوږ ورته ونه نیسئ او نور خلک تاسو بې لارې کړي او د نورو خدایانو عبادت وکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_17.mp3', '', 1761754199, 1761754199),
(38813, 'Deuteronomy 30:18', 'Deuteronomy', 30, 18, 'نو تاسو به تباه شئ. زه تاسو ته اوس همدلته خبرداری درکوم. تاسو به په هغه خاوره کې چې د اردن د سیند په بلې غاړې باندې پرته ده او زر به یې ونیسئ، ډېره موده ژوند ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_18.mp3', '', 1761754199, 1761754199),
(38814, 'Deuteronomy 30:19', 'Deuteronomy', 30, 19, 'زه اوس تاسو ته د ژوند او مرګ، د خدای د برکت او لعنت د غوره کولو حق درکوم او زه ځمکه او اسمان د دې خبرې دپاره شاهدان نیسم چې تاسو کوم شی غوره کوئ. تاسو ژوند غوره کړئ، ترڅو تاسو او ستاسو اولاده ژوندي پاتې شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_19.mp3', '', 1761754199, 1761754199),
(38815, 'Deuteronomy 30:20', 'Deuteronomy', 30, 20, 'خپل څښتن خدای ته پوره وفادار اوسئ، د هغه سره مینه کوئ او څه چې درته وایي هغه کوئ. یوازې څښتن دی چې ژوندون ورکولای شي. هغه به تاسو ته په هغه خاوره کې چې ستاسو د نیکونو ابراهیم، اسحاق او یعقوب سره یې وعده کړې ده، زیات عمر درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy30_verse_20.mp3', '', 1761754199, 1761754199),
(38816, 'Psalms 47:1', 'Psalms', 47, 1, 'ای ټولو خلکو پړکوئ لاسونه! د خدای ثنا په خوشحالۍ او لوړو چیغو وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_1.mp3', '', 1761754199, 1761754199),
(38817, 'Psalms 47:2', 'Psalms', 47, 2, 'چې هیبتناکه دی څښتن تعالی هغه ډېر لوی پاچا دی کوي حکومت ټولې دنیا باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_2.mp3', '', 1761754199, 1761754199),
(38818, 'Psalms 47:3', 'Psalms', 47, 3, 'نورو قومونو باندې مونږ ته یې بری راکړی او یې هغه قومونه لاندې کړل زمونږ تر‌پښو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_3.mp3', '', 1761754199, 1761754199),
(38819, 'Psalms 47:4', 'Psalms', 47, 4, 'ده غوره کړې ځمکه مونږ دپاره ویاړو پر دې مونږ د یعقوب اولاده خدای ورسره مینه چې کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_4.mp3', '', 1761754199, 1761754199),
(38820, 'Psalms 47:5', 'Psalms', 47, 5, 'وخاته خدای خپل تخت ته وې هلته چیغې د خوښۍ هلته غږونه د سرنو وو چې څښتن پورته لاړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_5.mp3', '', 1761754199, 1761754199),
(38821, 'Psalms 47:6', 'Psalms', 47, 6, 'وایاست سندرې او ثنا خدای ته! وایاست سندرې او ثنا خپل شاه ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_6.mp3', '', 1761754199, 1761754199),
(38822, 'Psalms 47:7', 'Psalms', 47, 7, 'ځکه چې خدای د ټول جهان پاچا دی ثنا یې ووایاست سندرې باندې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_7.mp3', '', 1761754199, 1761754199),
(38823, 'Psalms 47:8', 'Psalms', 47, 8, 'خدای کړي پاچاهي ټولو قومونو باندې خدای دی په خپل سپېڅلي تخت باندې ناست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_8.mp3', '', 1761754199, 1761754199),
(38824, 'Psalms 47:9', 'Psalms', 47, 9, 'د قومونو رهبران دي راټول شوي په یو ځای د ابراهیم د خدای د قومه سره د دنیا ټول شاهان د خدای واک کې دي هغه ډېر لوړ خدای دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms47_verse_9.mp3', '', 1761754199, 1761754199),
(38825, 'Joshua 24:1', 'Joshua', 24, 1, 'یوشع په شکیم کې د اسراییلو ټولې قبیلې راټولې کړې. هغه د اسراییلو سپین ږیري، مشران، قاضیان او مامورین راوغوښتل. هغوی راغلل او د خدای په حضور کې ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_1.mp3', '', 1761754199, 1761754199),
(38826, 'Joshua 24:2', 'Joshua', 24, 2, 'یوشع ټول قوم ته وویل: «د اسراییلو څښتن خدای داسې وایي: ‹ډېره موده مخکې ستاسو نیکونه چې په هغو کې د ابراهیم او د ناحور پلار یعنې تارح شامل ؤ، د فرات د سیند په بلې غاړې باندې اوسېدل او د نورو خدایانو عبادت به یې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_2.mp3', '', 1761754199, 1761754199),
(38827, 'Joshua 24:3', 'Joshua', 24, 3, 'بیا ما ستاسو نیکه ابراهیم د هغه ځای څخه بوته او د کنعان په ټوله خاوره کې مې وګرځاوه. هغه ته مې اسحاق ورکړ او د اسحاق په وسیله مې هغه ته ډېره اولاده ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_3.mp3', '', 1761754199, 1761754199),
(38828, 'Joshua 24:4', 'Joshua', 24, 4, 'اسحاق ته مې دوه زامن ورکړل یعنې یعقوب او عیسو. عیسو ته مې د ادوم غرنۍ سیمه د هغه د ملکیت په توګه ورکړه، خو ستاسو نیکه یعقوب او د هغه اولادونه مصر ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_4.mp3', '', 1761754199, 1761754199),
(38829, 'Joshua 24:7', 'Joshua', 24, 7, 'هغوی ماته د مرستې دپاره فریاد وکړ او ما د هغوی او مصریانو ترمنځ تیاره رامنځته کړه. په مصریانو باندې مې اوبه راوستلې او هغوی مې په بحیره کې ډوب کړل. تاسو په خپلو سترګو ولیدل چې ما په مصر باندې څه وکړل. له هغې وروسته تاسو ډېره موده په دښته کې اوسېدلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_7.mp3', '', 1761754199, 1761754199),
(38830, 'Joshua 24:8', 'Joshua', 24, 8, 'بیا مې تاسو هغې خاورې ته راوستلئ چې د اردن د سیند په ختیځ کې وه. هلته اموریان اوسېدل او هغوی ستاسو سره جګړه وکړه، خو تاسو زما په مرسته هغوی ته ماتې ورکړه، هغوی مو له منځه یووړل او د هغوی خاوره مو ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_8.mp3', '', 1761754199, 1761754199),
(38831, 'Joshua 24:9', 'Joshua', 24, 9, 'کله چې د موآب پاچا د صفور زوی بالاق ستاسو په وړاندې ودرېده، هغه د بعور زوی بلعام راوغوښت او د هغه څخه یې وغوښتل چې په تاسو باندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_9.mp3', '', 1761754199, 1761754199),
(38832, 'Joshua 24:10', 'Joshua', 24, 10, 'خو ما د بلعام خبرو ته غوږ ونه نیوه. هغه مې مجبور کړ چې تاسو ته برکت درکړي. په دې ډول مې تاسو د بالاق څخه وژغورلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_10.mp3', '', 1761754199, 1761754199),
(38833, 'Joshua 24:11', 'Joshua', 24, 11, 'بیا تاسو د اردن د سیند څخه پورې وتلئ او اریحا ته راغلئ. د اریحا خلکو د اموریانو، فرزیانو، کنعانیانو، حیتیانو، جرجاشیانو، حویانو او یبوسیانو په شان ستاسو سره جګړه وکړه. خو ما تاسو ته په هغوی ټولو باندې بری درکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_11.mp3', '', 1761754199, 1761754199),
(38834, 'Joshua 24:12', 'Joshua', 24, 12, 'ستاسو دښمنان ستاسو څخه وتښتېدل، خو ستاسو د تورو، لیندو او غشو له امله نه. ما ستاسو په دښمنانو کې سخته وېره راپیدا کړه او هغوی وتښتېدل لکه څنګه چې مې د هغو دوو اموریایي پاچاهانو سره کړي وو چې د اردن د سیند په ختیځ کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_12.mp3', '', 1761754199, 1761754199),
(38835, 'Joshua 24:13', 'Joshua', 24, 13, 'ما تاسو ته ځمکه درکړه په کومې باندې چې تاسو زحمت نه ؤ ویستلی او ښارونه مې درکړل چې هغه تاسو نه وو ودان کړي او اوس په هغو کې اوسېږئ. د انګورو او زیتونو د باغونو څخه چې تاسو کرلي نه وو، خواړه خورئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_13.mp3', '', 1761754199, 1761754199),
(38836, 'Joshua 24:14', 'Joshua', 24, 14, 'بیا یوشع وویل: «نو د څښتن څخه ووېرېږئ او په پوره وفادارۍ سره د هغه عبادت وکړئ. هغه بتان چې ستاسو نیکونو یې په مصر او د فرات د سیند په بله غاړه باندې عبادت کاوه، لېرې ګوزار کړئ او د څښتن عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_14.mp3', '', 1761754199, 1761754199),
(38837, 'Joshua 24:15', 'Joshua', 24, 15, 'که چېرې تاسو د هغه عبادت کول نه غواړئ، نو نن پرېکړه وکړئ چې د کومو خدایانو عبادت به کوئ. ایا د هغو خدایانو عبادت به کوئ چې ستاسو نیکونو یې د فرات د سیند په بله غاړه باندې عبادت کاوه او یا به د اموریانو د خدایانو چې تاسو اوس د هغوی په خاوره کې اوسېږئ، عبادت کوئ. خو زه به د خپلې کورنۍ سره د څښتن عبادت کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_15.mp3', '', 1761754199, 1761754199),
(38838, 'Joshua 24:16', 'Joshua', 24, 16, 'قوم په ځواب کې وویل: «مونږ به هېڅکله داسې ونه کړو چې څښتن پرېږدو او د نورو خدایانو عبادت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_16.mp3', '', 1761754199, 1761754199),
(38839, 'Joshua 24:17', 'Joshua', 24, 17, 'دا په خپله زمونږ څښتن خدای ؤ چې مونږ یې د خپلو نیکونو سره د مصر څخه چې په کې غلامان وو راوویستلو او مونږ هغه معجزې ولیدلې چې هغه وښودلې. په خپل ټول سفر کې او د هغو ټولو قومونو په منځ کې چې مونږ ورڅخه تېرېدلو، هغه وساتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_17.mp3', '', 1761754199, 1761754199),
(38840, 'Joshua 24:18', 'Joshua', 24, 18, 'څښتن زمونږ د مخې څخه هغه ټول قومونه لېرې کړل چې په دې خاوره کې اوسېدل چې په هغو کې اموریان هم شامل وو. نو مونږ به هم د څښتن عبادت او اطاعت کوو، ځکه چې هغه زمونږ خدای دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_18.mp3', '', 1761754199, 1761754199),
(38841, 'Joshua 24:19', 'Joshua', 24, 19, 'یوشع قوم ته وویل: «کېدای شي چې تاسو د څښتن عبادت ونه شئ کولای، ځکه چې هغه سپېڅلی او غیرتي خدای دی. تاسو باید هغه ته پوره وفادار اوسئ. که چېرې تاسو د هغه په وړاندې ګناه او سرکښي وکړئ، نو هغه به تاسې ونه بخښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_19.mp3', '', 1761754199, 1761754199),
(38842, 'Joshua 24:20', 'Joshua', 24, 20, 'که چېرې تاسو هغه پرېږدئ او د نورو قومونو د بتانو عبادت وکړئ، هغه به ستاسو په ضد شي او تاسو ته به سزا درکړي. که څه هم مخکې هغه ستاسو سره ښه ؤ، خو تاسې به له منځه یوسي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_20.mp3', '', 1761754199, 1761754199),
(38843, 'Joshua 24:21', 'Joshua', 24, 21, 'قوم یوشع ته وویل: «نه! مونږ به د څښتن عبادت او اطاعت کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_21.mp3', '', 1761754199, 1761754199),
(38844, 'Joshua 24:22', 'Joshua', 24, 22, 'یوشع هغوی ته وویل: «تاسو د خپلو ځانونو شاهدان یئ. تاسو وویل چې مونږ د څښتن عبادت او اطاعت کول غوره کړي دي.» هغوی وویل: «هو، مونږ شاهدان یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_22.mp3', '', 1761754199, 1761754199),
(38845, 'Joshua 24:23', 'Joshua', 24, 23, 'هغه غوښتنه وکړه: «خو لکه د هغو بتانو په شان چې نور قومونه یې عبادت کوي ستاسو سره هم یو څه بتان شته. هغه لېرې ګوزار کړئ او د اسراییلو د څښتن خدای سره د وفادارۍ لوظ وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_23.mp3', '', 1761754199, 1761754199),
(38846, 'Joshua 24:24', 'Joshua', 24, 24, 'قوم یوشع ته وویل: «مونږ به یوازې د خپل څښتن خدای عبادت کوو او د هغه حکمونو ته به غاړه ږدو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_24.mp3', '', 1761754199, 1761754199),
(38847, 'Joshua 24:25', 'Joshua', 24, 25, 'په هغه ورځ یوشع په شکیم کې د اسراییلو د خلکو استازیتوب وکړ او د هغوی او څښتن ترمنځ یې یو تړون وکړ او هغوی ته یې قوانین او اصول ورکړل چې ورڅخه پیروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_25.mp3', '', 1761754199, 1761754199),
(38848, 'Joshua 24:26', 'Joshua', 24, 26, 'یوشع دا خبرې د خدای د قوانینو په کتاب کې ولیکلې. بیا هغه یوه لویه تیږه واخیستله او د څښتن د عبادت په ځای کې یې د څېړۍ د ونې لاندې ودروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_26.mp3', '', 1761754199, 1761754199),
(38849, 'Joshua 24:27', 'Joshua', 24, 27, 'هغه ټول قوم ته وویل: «ګورئ، دا تیږه به زمونږ شاهده وي. دې تیږې هغه ټولې خبرې واورېدلې چې څښتن مونږ ته وکړې. نو که چېرې تاسو د خپل خدای څخه منکر شئ، نو دا تیږه به ستاسو په خلاف شهادت ورکوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_27.mp3', '', 1761754199, 1761754199),
(38850, 'Joshua 24:28', 'Joshua', 24, 28, 'بیا یوشع قوم رخصت کړ او هر یو کس د خپلې برخې ځمکې ته ور ستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_28.mp3', '', 1761754199, 1761754199),
(38851, 'Joshua 24:29', 'Joshua', 24, 29, 'څه موده وروسته د څښتن خدمتګار د نون زوی یوشع د یوسلو لسو کالو په عمر مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_29.mp3', '', 1761754199, 1761754199),
(38852, 'Joshua 24:30', 'Joshua', 24, 30, 'هغه یې په خپله ځمکه یعنې په تمنه سارح کې چې د افرایم په غرنۍ سیمه او د جاعش د غره په شمال کې وه، ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_30.mp3', '', 1761754199, 1761754199),
(38853, 'Joshua 24:31', 'Joshua', 24, 31, 'ترڅو پورې چې یوشع ژوندی ؤ، د اسراییلو خلکو د څښتن عبادت او اطاعت کاوه. حتی د هغه د مړینې څخه وروسته هم ترڅو پورې چې د قوم هغه سپین ږیري ژوندي وو چې د څښتن هغه ټول کارونه په خپلو سترګو لیدلي وو چې د اسراییلو دپاره یې کړي وو، هغوی څښتن ته وفادار پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_31.mp3', '', 1761754199, 1761754199),
(38854, 'Joshua 24:32', 'Joshua', 24, 32, 'د یوسف مړی چې د اسراییلو خلکو د مصر څخه راوړی ؤ، په شکیم کې په هغې ټوټه ځمکه کې ښخ کړای شو چې یعقوب د شکیم د ښار د بنیاد ایښودونکي حمور د زامنو څخه د سپینو زرو په سلو سکو باندې اخیستې وه. دا ځمکه د یوسف اولادې ته په میراث پاتې شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_32.mp3', '', 1761754199, 1761754199),
(38855, 'Joshua 24:33', 'Joshua', 24, 33, 'د هارون زوی العازار هم مړ شو او په جبعه کې چې د افرایم په غرنۍ سیمه کې یو ښارګوټی ؤ ښخ کړای شو، دا ښارګوټی د هغه زوی فینحاس ته ورکړل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua24_verse_33.mp3', '', 1761754199, 1761754199),
(38856, 'Psalms 70:1', 'Psalms', 70, 1, 'ای خدایه ته ما خلاص کړه ای څښتنه، زر کومک راسره وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms70_verse_1.mp3', '', 1761754199, 1761754199),
(38857, 'Psalms 70:2', 'Psalms', 70, 2, 'هغوی چې هڅه کوي ما ووژني هغوی دې ماتې سره مخ شي وارخطا دې شي چې زما په کړاوونو خوشحالي کړي هغوی دې تېښتې سره مخ شي او رسوا دې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms70_verse_2.mp3', '', 1761754199, 1761754199),
(38858, 'Psalms 70:3', 'Psalms', 70, 3, 'څوک چې په ما باندې ملنډې وهي له خپلې ماتې دې دوی وبوګنیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms70_verse_3.mp3', '', 1761754199, 1761754199),
(38859, 'Psalms 70:4', 'Psalms', 70, 4, 'هغه ټول خلک چې کړي تاته رجوع شي دې خوشحاله او خوښي دې کړي له تا نه هغه چې مینه کړي ستا د خلاصون سره او دوی دې تل وایي: «څومره عظیم دی خدای»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms70_verse_4.mp3', '', 1761754199, 1761754199),
(38860, 'Psalms 70:5', 'Psalms', 70, 5, 'زه یم غریب او زه محتاج یمه زر شه او زما کومک ته راشه خدایه ته مې مددګار او خلاصوونکی یې بیړه وکړه او کومک لره مې راشه ای څښتنه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms70_verse_5.mp3', '', 1761754199, 1761754199),
(38861, 'Joshua 13:1', 'Joshua', 13, 1, 'کله چې یوشع زوړ شو، څښتن هغه ته وویل: «ته ډېر زوړ شوی یې، خو ډېره ځمکه لا پاتې ده چې باید ونیول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_1.mp3', '', 1761754199, 1761754199),
(38862, 'Joshua 13:2', 'Joshua', 13, 2, 'دا هغه ځمکه ده چې پاتې ده: د فلسطینیانو او د جشوریانو ټوله سیمه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_2.mp3', '', 1761754199, 1761754199),
(38863, 'Joshua 13:3', 'Joshua', 13, 3, 'همدارنګه د عویانو سیمه تر جنوب پورې (د شیحور څخه نیولې چې د مصر په پولې کې وه د عقرون تر پولې پورې چې په شمال کې وه، د کنعانیانو ځمکه ګڼل کېدله. د فلسطین پاچاهان په غزه، اشدود، اشقلون، جت او عقرون کې اوسېدل)،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_3.mp3', '', 1761754199, 1761754199),
(38864, 'Joshua 13:4', 'Joshua', 13, 4, 'د کنعانیانو ټول هېواد او میعاره چې په صیدونیانو پورې اړه لري تر افیق پورې چې د اموریانو په پوله کې دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_4.mp3', '', 1761754199, 1761754199),
(38865, 'Joshua 13:5', 'Joshua', 13, 5, 'د جبالیانو ځمکه او ټول لبنان تر ختیځ پورې، د بعل جاد څخه نیولې چې د حرمون د غره جنوب خواته پروت دی د حمات تر غاښي پورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_5.mp3', '', 1761754199, 1761754199),
(38866, 'Joshua 13:6', 'Joshua', 13, 6, 'په دې کې د صیدونیانو چې د لبنان د غرونو او د مسرفوت مایم ترمنځ په غرنۍ سیمه کې اوسیږي، ټوله سیمه شامله ده. زه به په خپله د اسراییلو له مخې څخه دا خلک لېرې کړم. څنګه چې ما په تا باندې حکم کړی دی، ته باید دا ځمکه د اسراییلیانو په منځ کې ووېشې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_6.mp3', '', 1761754199, 1761754199),
(38867, 'Joshua 13:7', 'Joshua', 13, 7, 'بیا دا ځمکه په هغو نهو قبیلو او د منسي په نیمې قبیلې ووېشه چې تر اوسه پورې ځمکه نه لري چې د هغوی ملکیت شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_7.mp3', '', 1761754199, 1761754199),
(38868, 'Joshua 13:8', 'Joshua', 13, 8, 'موسی لا پخوا د روبین او جاد قبیلو او د منسي بلې نیمې قبیلې ته هغه ځمکه ورکړې وه چې د اردن د سیند په ختیځه غاړه باندې پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_8.mp3', '', 1761754199, 1761754199),
(38869, 'Joshua 13:9', 'Joshua', 13, 9, 'دا سیمه د هغه ښار څخه چې د ارنون د درې په منځ کې ؤ او په هغې کې د عروعیر ښار چې د هغې درې په شمالي څنډه کې ؤ شامل ؤ، شمال خواته غزېدلې ده. په هغې کې د دیبون په شمال کې د میدیبا لوړه جلګه شامله وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_9.mp3', '', 1761754199, 1761754199),
(38870, 'Joshua 13:10', 'Joshua', 13, 10, 'د هغوی سیمه د عمون تر پولې پورې رسېدله. همدارنګه په هغې کې هغه ټول ښارونه هم شامل وو چې د اموریانو پاچا سیحون به ورباندې د حشبون د ښار څخه حکومت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_10.mp3', '', 1761754199, 1761754199),
(38871, 'Joshua 13:11', 'Joshua', 13, 11, 'په هغې کې جلعاد، د جشور او معکې سیمې، د حرمون ټول غر او ټول باشان تر سلخه پورې شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_11.mp3', '', 1761754199, 1761754199),
(38872, 'Joshua 13:12', 'Joshua', 13, 12, 'په هغې کې د عوج پاچاهي شامله وه. عوج د رفاییانو د جملې څخه یوازېنی کس ؤ چې ژوندی پاتې شوی ؤ او په عشتاروت او ادرعي کې یې پاچاهي کوله. موسی دې خلکو ته ماتې ورکړې وه او هغوی یې شړلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_12.mp3', '', 1761754199, 1761754199),
(38873, 'Joshua 13:13', 'Joshua', 13, 13, 'خو بیاهم اسراییلیانو جشوریان او معکیان ونه شړل، نو هغوی تر نن ورځې پورې د اسراییلیانو په منځ کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_13.mp3', '', 1761754199, 1761754199),
(38874, 'Joshua 13:14', 'Joshua', 13, 14, 'موسی د لاوي قبیلې ته هېڅ ځمکه نه وه ورکړې، ځکه چې د اسراییلو څښتن خدای هغوی ته ویلي وو: «تاسو به د ځمکې په ځای هغه قربانۍ تر لاسه کوئ چې زما د قربانۍ په ځای باندې سوځول کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_14.mp3', '', 1761754199, 1761754199),
