(38889, 'Joshua 13:29', 'Joshua', 13, 29, 'موسی د منسي په نیمه قبیله کې هرې یوې طایفې ته ځمکه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_29.mp3', '', 1761754199, 1761754199),
(38890, 'Joshua 13:30', 'Joshua', 13, 30, 'د هغوی سیمه تر محنایم پورې وه او په هغې کې د باشان پاچا عوج ټوله پاچاهي او همدارنګه په باشان کې د یاییر ټول شپېته کلي شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_30.mp3', '', 1761754199, 1761754199),
(38891, 'Joshua 13:31', 'Joshua', 13, 31, 'په دې کې نیم جلعاد، همدارنګه عشتاروت او ادرعي یعنې په باشان کې د عوج د پاچاهۍ شاهي ښارونه شامل وو. دا ټول هغو نیمو طایفو ته ورکړل شول چې د ماخیر یعنې د منسي د زوی څخه د اولادې په توګه پاتې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_31.mp3', '', 1761754199, 1761754199),
(38892, 'Joshua 13:32', 'Joshua', 13, 32, 'په دې ډول موسی د موآب ډاګونه چې د اردن د سیند په بله غاړه او د اریحا په ختیځ کې وو، ووېشل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_32.mp3', '', 1761754199, 1761754199),
(38893, 'Joshua 13:33', 'Joshua', 13, 33, 'خو موسی د لاوي قبیلې ته هېڅ ځمکه ورنه کړه، ځکه چې څښتن وعده کړې وه چې هغه به تل د هغوی اړتیاوې پوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua13_verse_33.mp3', '', 1761754199, 1761754199),
(38894, 'Jeremiah 47:1', 'Jeremiah', 47, 1, 'دا د مالِک خُدائ هغه کلام دے چې د فِرعون د لښکرو په غزه د حملې کولو نه مخکښې، په يرمياه نبى د فلستيانو په حقله نازل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_1.mp3', '', 1761754199, 1761754199),
(38895, 'Jeremiah 47:2', 'Jeremiah', 47, 2, '”مالِک خُدائ وفرمائيل چې، وګوره، د شمال نه اوبۀ څنګه راوچتيږى، او د سېلاب په شان په زور شور راروانې دى، دا به ټوله زمکه او هر څۀ چې په کښې دى رالاندې کړى، ښارونه او د هغې اوسېدونکى به ډوب کړى، ټول خلق به د مدد دپاره چغې وهى او څومره خلق چې په کښې اوسيږى هغوئ به ژړا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_2.mp3', '', 1761754199, 1761754199),
(38896, 'Jeremiah 47:3', 'Jeremiah', 47, 3, 'هغوئ به د آسونو د سومونو او پښو ټکار واورى، او د دشمن د جنګى ګاډو غرار او د هغوئ د پايو شور به واورى. پلاران به د يرې نه جام شى او د خپلو بې‌وسه ماشومانو د بچ کولو دپاره به شاته نۀ ګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_3.mp3', '', 1761754199, 1761754199),
(38897, 'Jeremiah 47:4', 'Jeremiah', 47, 4, 'د ټولو فلستيانو د تباهۍ ورځ رارسېدلې ده او ورسره د هغوئ هم څوک چې به د صور او صيدا خلقو سره مدد کوى. مالِک خُدائ په خپله هغه فلستيان تباه کوى، هغوئ څوک چې ژوندى پاتې شوى دى او د کريت د ساحل نه راغلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_4.mp3', '', 1761754199, 1761754199),
(38898, 'Jeremiah 47:5', 'Jeremiah', 47, 5, 'غزه لور به د غم نه خپل سر ګنجے کړى او د اسقلون ښار به وران او خاموشه شى. اے د مېدانى علاقې پاتې شوو خلقو ترڅو پورې به خپل ځان وهئ او ماتم به کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_5.mp3', '', 1761754199, 1761754199),
(38899, 'Jeremiah 47:6', 'Jeremiah', 47, 6, 'تاسو چغې وهئ، اے د مالِک خُدائ تُورې، ترڅو پورې به تۀ زخمى کول کوې؟ خپل کاش ته واپس لاړه شه، او هلته په آرام پرته اوسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_6.mp3', '', 1761754199, 1761754199),
(38900, 'Jeremiah 47:7', 'Jeremiah', 47, 7, 'خو دا به څنګه په آرام شى چې ورته مالِک خُدائ حکم کړے دے، کله چې هغۀ ورته په اسقلون او په ساحل د حملې کولو حکم کړے دے؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah47_verse_7.mp3', '', 1761754199, 1761754199),
(38901, 'Proverbs 26:1', 'Proverbs', 26, 1, 'لکه څنګه چې په اوړي کې واوره او د لو په وخت کې باران مناسب نه دی همداسې کم‌عقل انسان ته درناوی کول هم مناسب نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_1.mp3', '', 1761754199, 1761754199),
(38902, 'Proverbs 26:2', 'Proverbs', 26, 2, 'لکه څنګه چې چڼچڼه اخوا دې خوا الوزي او یا توتکۍ ګرځي راګرځي او نه کښېني همداسې بېځایه سپکې سپورې په چا پورې نه نښلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_2.mp3', '', 1761754199, 1761754199),
(38903, 'Proverbs 26:3', 'Proverbs', 26, 3, 'لکه څنګه چې د اس دپاره قمچینه او د خره دپاره قیضه ده همداسې د کم‌عقلانو د ملا دپاره لښته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_3.mp3', '', 1761754199, 1761754199),
(38904, 'Proverbs 26:4', 'Proverbs', 26, 4, 'کم‌عقل ته د هغه د جهالت سره سم ځواب مه ورکوه هسې نه چې ته په خپله هم د هغه په شان شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_4.mp3', '', 1761754199, 1761754199),
(38905, 'Proverbs 26:5', 'Proverbs', 26, 5, 'کم‌عقل ته د هغه د جهالت سره سم ځواب ورکوه هسې نه چې هغه ځان د حکمت خاوند وګڼي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_5.mp3', '', 1761754199, 1761754199),
(38906, 'Proverbs 26:6', 'Proverbs', 26, 6, 'د کم‌عقل په لاس پیغام لېږل داسې دي لکه خپلې پښې غوڅول او د ظلم زهر څښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_6.mp3', '', 1761754199, 1761754199),
(38907, 'Proverbs 26:7', 'Proverbs', 26, 7, 'د کم‌عقل د خولې متل داسې دی لکه د ګوډ سړي پښه چې بېځایه زنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_7.mp3', '', 1761754199, 1761754199),
(38908, 'Proverbs 26:8', 'Proverbs', 26, 8, 'کم‌عقل ته درناوی کول داسې دي لکه څوک چې په مچنوغزه کې تیږه د سر نه تاوه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_8.mp3', '', 1761754199, 1761754199),
(38909, 'Proverbs 26:9', 'Proverbs', 26, 9, 'د کم‌عقل د خولې متل داسې دی لکه د نشه انسان په لاس کې چې د اغزیو لښته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_9.mp3', '', 1761754199, 1761754199),
(38910, 'Proverbs 26:10', 'Proverbs', 26, 10, 'هغه څوک چې کم‌عقل او لاروی سړی مزدور نیسي د هغه غشي ویشتونکي په څېر دی چې هرڅوک ټپي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs26_verse_10.mp3', '', 1761754199, 1761754199);